using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using Newtonsoft.Json;using MediaBrowser.Common;using MediaBrowser.Model.Serialization;using Emby.Theater.App;
class RuntimeIdentity {static string H(string p){using(var h=SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}static object A(Assembly a){return new {identity=a.FullName,location=a.Location,sha256=H(a.Location),gac=a.GlobalAssemblyCache};}static int Main(){Console.WriteLine(JsonConvert.SerializeObject(new {clr=Environment.Version.ToString(),pointerSize=IntPtr.Size,objectAssembly=typeof(object).Assembly.FullName,host=A(typeof(ApplicationHost).Assembly),model=A(typeof(IJsonSerializer).Assembly),common=A(typeof(IApplicationHost).Assembly),newtonsoft=A(typeof(JsonConvert).Assembly)},Formatting.Indented));return IntPtr.Size==4?0:1;}}
